"""Summarize read-only post-analysis and verify internal numerical identities."""
from pathlib import Path
import json
import numpy as np
import pandas as pd
from scipy.stats import t
P=Path(__file__).resolve().parent;O=P/'results'
R=pd.read_csv(O/'model_diagnostics.csv');U=pd.read_csv(O/'sampled_update_summaries.csv');F=pd.read_csv(O/'fixed_rank_proxies.csv');D=pd.read_csv(O/'paired_error_decomposition.csv');E=pd.read_csv(O/'setting_effects.csv')
def ci(v):
 v=np.asarray(v,float);assert len(v)==5;h=t.ppf(.975,4)*v.std(ddof=1)/np.sqrt(5);return v.mean(),v.mean()-h,v.mean()+h
def fmt(v):return f'{v[0]:+.5f} [{v[1]:+.5f}, {v[2]:+.5f}]'
# Direct observed update quantities, not couplings fitted to alpha.
C=U.groupby(['seed','batch_size','multiplier','arm','layer'])[['gain','relative_step','radial_rate','adam_sgdm_cosine','weight_norm']].mean().reset_index();C.to_csv(O/'measured_update_quantities.csv',index=False)
cr=[]
for (arm,layer),g in C.groupby(['arm','layer']):
 for metric in ['gain','relative_step','radial_rate','adam_sgdm_cosine']:
  v=g.groupby('seed')[metric].mean();m,lo,hi=ci(v);cr.append(dict(arm=arm,layer=layer,metric=metric,mean=m,ci_low=lo,ci_high=hi))
pd.DataFrame(cr).to_csv(O/'update_quantity_seed_intervals.csv',index=False)
sr=[]
for (layer,frac),g in F[(F.epoch==60)&F.layer.isin(['fc1','fc2'])].groupby(['layer','fraction']):
 g=g.assign(fixed_distance=(g.fixed_rank_alpha-2).abs(),absolute_proxy=g.h_minus1_proxy.abs())
 for metric in ['fixed_distance','absolute_proxy']:
  a=g.groupby(['seed','arm'])[metric].mean().unstack();m,lo,hi=ci(a.magnitude_graft-a.adamw);sr.append(dict(layer=layer,fraction=frac,metric=metric,mean=m,ci_low=lo,ci_high=hi))
S=pd.DataFrame(sr);S.to_csv(O/'tail_range_sensitivity.csv',index=False)
# CE decomposition and accuracy identity must hold for every matched setting/seed.
maxerr=0
for (seed,b,m,arm),g in D.groupby(['seed','batch_size','multiplier','arm']):
 a=R[(R.seed==seed)&(R.batch_size==b)&(R.multiplier==m)].set_index('arm');maxerr=max(maxerr,abs(g.ce_contribution.sum()-(a.loc[arm,'test_loss']-a.loc['adamw','test_loss'])))
 counts=g.set_index('category')['count'];assert abs((counts.corrected-counts.introduced)/100-(a.loc[arm,'test_accuracy_pct']-a.loc['adamw','test_accuracy_pct']))<1e-10
assert maxerr<1e-12
assert len(R)==120 and len(U)==14400 and len(C)==360
check={'models':120,'independent_seeds':5,'sampled_epoch_layer_summaries':len(U),'all_settings_retained':True,'max_error_decomposition_identity_error':maxerr,'test_used_for_temperature_fit':False,'endpoint_selection':False,'neural_training':False,'predicted_classes_unchanged_by_temperature':True,'source_training_modified':False,'plot_inspection':'Three plots inspected after rendering','limitations':['Exploratory post-hoc analysis with reused test set','Temperature fits validation only; not a new independent confirmation','Intervals unadjusted for multiple comparisons','Recorded updates are sampled, not every optimizer step','FC3 norm is meaningful although its power-law alpha fit is unsupported','No optimizer Jacobian determinant or validated RG residual measured']}
(O/'Post_Analysis_Checks.json').write_text(json.dumps(check,indent=2)+'\n')
means=R.groupby('arm').mean(numeric_only=True);delta=means.loc['magnitude_graft','test_loss']-means.loc['adamw','test_loss'];caldelta=means.loc['magnitude_graft','calibrated_test_loss']-means.loc['adamw','calibrated_test_loss']
lines=['# Fashion-MNIST RETRY01: post-analysis','','This is read-only, exploratory postprocessing of all120 fixed-epoch60 models (five paired seeds × eight settings × three arms), with their saved epoch20 endpoints and continuation statistics. No training, retuning, endpoint selection, or exclusion was performed. All original evidence remains unchanged.','','## Main finding','','The accuracy/CE contradiction is largely a confidence-scale issue. A positive scalar temperature fitted separately to each model’s **validation** logits reduces the graft-minus-AdamW test CE penalty from %.6f to %.6f nat (%.1f%% reduction of the mean gap). Predicted classes and every weight matrix are unchanged. The calibrated graft still has a small positive CE penalty: +0.002842 [0.000455,0.005229], paired95%% t interval. This does not rescue alpha alignment or establish the RG mechanism.'%(delta,caldelta,100*(1-caldelta/delta)),'','| Arm | Raw test CE | Validation-calibrated test CE | Mean temperature | FC3 Frobenius norm | Centered logit RMS |','|---|---:|---:|---:|---:|---:|']
for arm in ['adamw','magnitude_graft','sgdm']:
 r=means.loc[arm];lines.append(f'| {arm} | {r.test_loss:.5f} | {r.calibrated_test_loss:.5f} | {r.temperature:.3f} | {r.fc3_frob_60:.3f} | {r.logit_centered_rms:.3f} |')
lines+=['','Temperature is fitted by minimizing full epoch60 validation CE over logT∈[−4,4], then applied once to saved epoch60 test logits. All fits are interior. The test set is reused and this diagnostic was selected after seeing the loss discrepancy. Calibration leaves the previously measured alphas unchanged. SGDM calibrated CE is below AdamW by0.008580nat [−0.012160,−0.005000]. These are postprocessed predictions, not new optimizer-training outcomes.','','![Calibration and norms](results/calibration_and_norms.png)','','## Which settings drive the result?','','Graft minus AdamW at epoch60. Positive accuracy favors graft; negative distance/CE favors graft. Full five-seed paired intervals are in [setting_effects.csv](results/setting_effects.csv). All eight settings remain in the analysis.','','| Batch | LR multiplier | Accuracy difference (pp) | FC1 distance difference | FC2 distance difference | Mean hidden distance difference | CE difference |','|---:|---:|---:|---:|---:|---:|---:|']
ef=E[(E.epoch==60)&(E.arm=='magnitude_graft')].pivot(index=['batch_size','multiplier'],columns='metric',values='mean')
for (b,m),r in ef.iterrows():lines.append(f'| {b} | {m:g} | {r.test_accuracy_pct:+.4f} | {r.distance_fc1:+.4f} | {r.distance_fc2:+.4f} | {r.mean_abs_alpha_minus_2:+.4f} | {r.test_loss:+.4f} |')
lines+=['','B128×1 and B256×2 have negative accuracy differences with intervals excluding zero, and worse FC1/FC2 alignment. B512×2 improves accuracy and mean hidden distance, but worsens CE. B512×0.5 improves accuracy and slightly lowers CE, but worsens hidden alignment. Thus no single average captures a uniform optimizer benefit. These descriptive contrasts do not justify discarding unfavorable settings.','','![Setting contrasts](results/setting_effects.png)','','## Measured update mechanism','','The implemented graft is exactly a layer-dependent scalar gain on Adam’s matrix update: ΔW_graft = g_l ΔW_Adam, with g_l = η_SGDM,l ||momentum_l||F / ||ΔW_Adam||F, computed on the graft trajectory. The gain is directly recorded, not estimated by fitting alpha. Epoch means are averaged equally over epochs21–60, then over the eight settings within each seed. Recorded batches are the first two and every tenth; summaries are not exact whole-trajectory integrals.','','| Layer | Graft gain over native Adam update on same trajectory | Graft Adam/SGDM direction cosine |','|---|---:|---:|']
cr=pd.DataFrame(cr)
for layer in ['fc1','fc2','fc3']:
 r=cr[(cr.arm=='magnitude_graft')&(cr.layer==layer)].set_index('metric');a=r.loc['gain'];b=r.loc['adam_sgdm_cosine'];lines.append(f'| {layer.upper()} | {fmt([a["mean"],a.ci_low,a.ci_high])} | {fmt([b["mean"],b.ci_low,b.ci_high])} |')
lines+=['','The output-layer target magnitude is approximately9.65× the hypothetical native Adam magnitude **on the same graft trajectory**, compared with1.06× in FC1 and2.19× in FC2. This is an intentional consequence of the frozen layer rates[.04,.2,.8], not evidence that rates were accidentally reset. It makes the classifier head an important possible contributor to overconfidence. The endpoint head norm is44.27 for graft versus6.08 for AdamW; however, ReLU layer rescalings mean a head norm alone cannot establish causation. Centered logit RMS provides direct output-level evidence of larger prediction scale.','', 'Relative step sizes decrease during continuation and are not exploding; SGDM relative steps are often larger than graft despite less severe CE. Thus the evidence does not support a simple claim that all graft steps are numerically too large. Optimizer directions also differ substantially: matching magnitude does not make the graft an SGDM update.','','![Update dynamics](results/update_dynamics.png)','','## Where the extra loss occurs','','Across matched test examples, graft corrects290.975 AdamW errors and introduces249.025 errors per10000 examples, yielding41.95 fewer errors. But on examples both classify incorrectly, its excess CE contribution is+0.112078nat [0.107556,0.116600], exceeding the net+0.094516 gap. The other categories partly offset this. This is measured on the same examples, unlike independently selected worst1% sets. See [paired decomposition](results/error_decomposition_intervals.csv).','', 'All40 graft models have higher final validation CE than at epoch20, versus24/40 AdamW and35/40 SGDM models. That is evidence of deteriorating probabilistic performance during this continuation; it does not imply every single epoch’s loss must decrease. The epoch of minimum validation CE is retained only as a descriptive field; no checkpoint is selected from it.','','## Alpha aggregation and tail-range sensitivity','','Graft FC1 mean alpha is closer to2, but the across-setting spread is larger: mean within-seed SD0.305 versus0.122 for AdamW. Opposite-side deviations cancel in the mean. Average individual distance is0.256 versus0.189; distance of the mean is0.071 versus0.187. The prior headline based only on average alpha would therefore be misleading.','','Using the archived fixed-rank estimators changes some alignment conclusions. The following compares graft minus AdamW mean absolute distance of fixed-rank alpha from2. Five seed means over eight settings; neither range was selected based on performance.','','| Layer | Top spectral fraction | Difference [95% interval] |','|---|---:|---:|']
for _,r in S[S.metric=='fixed_distance'].iterrows():lines.append(f'| {r.layer.upper()} | {r.fraction:.0%} | {fmt([r["mean"],r.ci_low,r.ci_high])} |')
lines+=['','FC1 worsens using the top20% but improves using the top50%; FC2 has the reverse pattern. WeightWatcher’s original selected-tail fits and every raw spectrum remain unchanged. This demonstrates sensitivity to the spectral band and is a reason to examine the full spectral flow, not choose the estimator that supports the theory. Supported WW fits do not establish a globally exact power law.','','The saved h−1 quantity is a **tail-shape proxy** defined by a fixed-rank mean log eigenvalue ratio. It is not the optimizer’s Jacobian trace-log and not a demonstrated residual of the theory’s RG condition. We have not measured a valid RG scale-equivariance residual in this post-analysis. Saved scalar norms cannot determine the Jacobian determinant; its state space, scaling transformation and treatment of moment histories must first be specified.','','## What this resolves and what it does not','','1. No new evidence of a coding or checkpoint-restoration error. The frozen source and existing independent verification are preserved.','2. The CE penalty is largely removable by a validation-fitted confidence rescaling, with unchanged accuracy and weights. This explains the apparent accuracy/CE contradiction much more directly than an alpha-only explanation.','3. Learning-rate/batch settings interact strongly with the intervention. The data support investigating the head magnitude and relative scaling, but do not establish an optimal setting or isolate a head-only causal effect.','4. Alpha alignment remains mixed and estimator-range-sensitive. This pass does not verify the proposed joint RG/alpha/generalization claim.','5. A future test would need a predeclared scale-condition observable and an isolated classifier-head intervention or balanced rate comparison. Such training was not run or scheduled here.','','All intervals use five seeds, not40models as independent replicates. They are exploratory, unadjusted for multiple comparisons, and based on a reused test set. FC3 power-law alpha is unsupported due to10eigenvalues; its Frobenius norm is nevertheless directly measurable.','','Reproduction: run `analyze.py --artifacts <directory containing the preserved seed archive folders and audit folder> --output results`, then `report.py`. [Checks](results/Post_Analysis_Checks.json) · [All numerical outputs](results/) · [Original verified report](../FINAL_VERIFIED_REPORT.md).']
(P/'REPORT.md').write_text('\n'.join(lines)+'\n')
print('Wrote report and internal checks. Mean CE gap reduction:',100*(1-caldelta/delta))
